'use client';

import React from 'react';
import Link from "next/link";
import { Receipt } from "lucide-react";
import { TransactionProvider } from "@/lib/transaction-context";

export default function DashboardLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <TransactionProvider>
      <div className="min-h-screen flex flex-col">
        {/* Top Navigation */}
        <header className="bg-[#111827] text-white shadow-md">
          <div className="w-full px-4 sm:px-6 lg:px-8">
            <div className="flex justify-between h-16 items-center">
              <div className="flex items-center">
                <div className="flex-shrink-0 flex items-center gap-2">
                  <div className="bg-green-500 p-1 rounded">
                    <Receipt className="h-6 w-6 text-white" />
                  </div>
                  <span className="text-xl font-bold tracking-tight">Finora</span>
                </div>
                <nav className="hidden md:ml-10 md:flex md:space-x-8">
                  <Link href="/dashboard" className="text-gray-300 hover:text-white px-3 py-2 rounded-md text-sm font-medium transition-colors">
                    Overview
                  </Link>
                  <Link href="/transactions" className="text-gray-300 hover:text-white px-3 py-2 rounded-md text-sm font-medium transition-colors">
                    Transactions
                  </Link>
                  <Link href="/analytics" className="text-gray-300 hover:text-white px-3 py-2 rounded-md text-sm font-medium transition-colors">
                    Reports
                  </Link>
                  <Link href="/budgets" className="text-gray-300 hover:text-white px-3 py-2 rounded-md text-sm font-medium transition-colors">
                    Budgets
                  </Link>
                  <Link href="/scanner" className="text-gray-300 hover:text-white px-3 py-2 rounded-md text-sm font-medium transition-colors">
                    AI Scan
                  </Link>
                  <Link href="/settings" className="text-gray-300 hover:text-white px-3 py-2 rounded-md text-sm font-medium transition-colors">
                    Settings
                  </Link>
                </nav>
              </div>
              <div className="flex items-center gap-4">
                <div className="flex items-center gap-2">
                  <Link href="/login">
                  <div className="h-8 w-8 rounded-full bg-green-500 flex items-center justify-center text-white font-bold cursor-pointer">
                    TE
                  </div>
                  </Link>
                </div>
              </div>
            </div>
          </div>
        </header>

        {/* Main Content */}
        <main className="flex-1 w-full px-4 sm:px-6 lg:px-8 py-8">
          {children}
        </main>
      </div>
    </TransactionProvider>
  );
}
