'use client';

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';

export type TransactionType = 'Income' | 'Expense';

export interface Transaction {
  id: string;
  date: string;
  description: string;
  category: string;
  amount: number;
  type: TransactionType;
  status: 'Completed' | 'Pending' | 'Failed';
  paymentMethod: string;
}

export interface UserProfile {
  name: string;
  email: string;
}

interface TransactionContextType {
  transactions: Transaction[];
  addTransaction: (transaction: Omit<Transaction, 'id'>) => void;
  deleteTransaction: (id: string) => void;
  stats: {
    totalIncome: number;
    totalExpense: number;
    netProfit: number;
  };
  budgetLimit: number; // Dynamic Budget Limit
  updateBudgetLimit: (amount: number) => void;
  userProfile: UserProfile;
  updateUserProfile: (profile: UserProfile) => void;
}

const TransactionContext = createContext<TransactionContextType | undefined>(undefined);

const initialTransactions: Transaction[] = [
  { id: '1', date: '2025-05-24', description: 'Payment from Client', category: 'Income', amount: 5000.00, type: 'Income', status: 'Completed', paymentMethod: 'Bank Transfer' },
  { id: '2', date: '2025-05-23', description: 'Office Supplies', category: 'Supplies', amount: 120.50, type: 'Expense', status: 'Completed', paymentMethod: 'Credit Card' },
  { id: '3', date: '2025-05-22', description: 'Monthly Rent', category: 'Housing', amount: 2000.00, type: 'Expense', status: 'Completed', paymentMethod: 'Bank Transfer' },
  { id: '4', date: '2025-05-21', description: 'Freelance Project', category: 'Income', amount: 1500.00, type: 'Income', status: 'Pending', paymentMethod: 'PayPal' },
  { id: '5', date: '2025-05-20', description: 'Grocery Shopping', category: 'Food', amount: 350.00, type: 'Expense', status: 'Completed', paymentMethod: 'Cash' },
  { id: '6', date: '2025-05-19', description: 'Internet Bill', category: 'Utilities', amount: 80.00, type: 'Expense', status: 'Completed', paymentMethod: 'Credit Card' },
  { id: '7', date: '2025-05-18', description: 'Consulting Fee', category: 'Income', amount: 2500.00, type: 'Income', status: 'Completed', paymentMethod: 'Bank Transfer' },
];

export function TransactionProvider({ children }: { children: ReactNode }) {
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [stats, setStats] = useState({ totalIncome: 0, totalExpense: 0, netProfit: 0 });
  const [budgetLimit, setBudgetLimit] = useState<number>(0); // Initialize with 0, load later
  const [userProfile, setUserProfile] = useState<UserProfile>({ name: '', email: '' });
  const [isLoaded, setIsLoaded] = useState(false);

  useEffect(() => {
    // Load from localStorage on mount
    const saved = localStorage.getItem('finora_transactions');
    const savedLimit = localStorage.getItem('finora_budget_limit');
    const savedProfile = localStorage.getItem('finora_user_profile');
    
    if (saved) {
      try {
        setTransactions(JSON.parse(saved));
      } catch (e) {
        setTransactions(initialTransactions);
      }
    } else {
      setTransactions(initialTransactions);
    }

    if (savedLimit) {
      setBudgetLimit(parseFloat(savedLimit));
    }

    if (savedProfile) {
      try {
        setUserProfile(JSON.parse(savedProfile));
      } catch (e) {
        console.error("Failed to parse user profile from local storage");
      }
    }

    setIsLoaded(true);
  }, []);

  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem('finora_transactions', JSON.stringify(transactions));
    }
  }, [transactions, isLoaded]);

  const updateUserProfile = (profile: UserProfile) => {
    setUserProfile(profile);
    localStorage.setItem('finora_user_profile', JSON.stringify(profile));
  };

  useEffect(() => {
    const totalIncome = transactions
      .filter(t => t.type === 'Income')
      .reduce((acc, curr) => acc + curr.amount, 0);
    
    const totalExpense = transactions
      .filter(t => t.type === 'Expense')
      .reduce((acc, curr) => acc + curr.amount, 0);

    setStats({
      totalIncome,
      totalExpense,
      netProfit: totalIncome - totalExpense
    });
  }, [transactions]);

  const addTransaction = (transaction: Omit<Transaction, 'id'>) => {
    const newTransaction = {
      ...transaction,
      id: Math.random().toString(36).substr(2, 9),
    };
    setTransactions(prev => [newTransaction, ...prev]);
  };

  const deleteTransaction = (id: string) => {
    setTransactions(prev => prev.filter(t => t.id !== id));
  };

  const updateBudgetLimit = (amount: number) => {
    setBudgetLimit(amount);
    localStorage.setItem('finora_budget_limit', amount.toString());
  };

  return (
    <TransactionContext.Provider value={{ 
      transactions, 
      addTransaction, 
      deleteTransaction, 
      stats,
      budgetLimit,
      updateBudgetLimit,
      userProfile,
      updateUserProfile
    }}>
      {children}
    </TransactionContext.Provider>
  );
}

export function useTransactions() {
  const context = useContext(TransactionContext);
  if (context === undefined) {
    throw new Error('useTransactions must be used within a TransactionProvider');
  }
  return context;
}
